                public class HandleIncomingPacket_0_1_Request {
                    public const uint fixed_port_id = 500;
                    /**
                    This field shall contain the same value that was used by the local node when sending the corresponding
                    outgoing packet using the message type OutgoingPacket. This value will be used by the local node to match the
                    response with its local context.
                    */
                    ushort session_id;
                    /**
                    Effective payload. This data will be forwarded from the remote host verbatim. UDP packets that contain more
