            public class NodeIDAllocationData_2_0 {
                public const uint fixed_port_id = 8165;
                /**
                If the message transfer is anonymous (i.e., allocation request), this is the preferred ID. If the message
                transfer is non-anonymous (i.e., allocation response), this is the allocated ID. If the allocatee does not
                have any preference, it should request the highest possible node-ID. Keep in mind that the two highest node-ID
                values are reserved for network maintenance tools; requesting those is not prohibited, but the allocator is
                recommended to avoid granting these node-ID, using nearest available lower value instead. The allocator will
                traverse the allocation table starting from the preferred node-ID upward, until a free node-ID is found (or
                the first ID reserved for network maintenance tools is reached). If a free node-ID could not be found, the
                allocator will restart the search from the preferred node-ID downward, until a free node-ID is found.
                */
                node.ID_1_0 node_id;
                /**
                The unique-ID of the allocatee. This is the SAME value that is reported via uavcan.node.GetInfo. The value is
                subjected to the same set of constraints; e.g., it can't be changed while the node is running, and the same
                value should be unlikely to be used by any two different nodes anywhere in the world. If this is a
                non-anonymous transfer (i.e., allocation response), allocatees will match this value against their own
                unique-ID, and ignore the message if there is no match. If the IDs match, then the field node_id contains the
                allocated node-ID value for this node.
                */
                [D(16)] byte[] unique_id;
            }

