            publishTimeSync() { for (i := 0; i &lt; NUM_IFACES; i++) { message := uavcan.time.Synchronization();
            message.previous_transmission_timestamp_usec := previous_tx_timestamp_per_iface[i];
            previous_tx_timestamp_per_iface[i] := 0; publishMessage(transfer_id, i, message); } transfer_id++; // Overflow
            shall be handled correctly }
