            previous_transfer_id := 0; state := STATE_UPDATE;                      // Variants: STATE_UPDATE, STATE_ADJUST
            master_node_id := -1;                       // Invalid value iface_index := -1;                          //
            Invalid value
            // This function adjusts the local clock by the specified amount function adjustLocalTime(phase_error);
            function adjust(message) { // Clock adjustment will be performed every second message local_time_phase_error
            := previous_rx_real_timestamp - msg.previous_transmission_timestamp_microsecond;
