            }

            /**
            This data types defines constants and runtime values pertaining to the International Atomic Time, also known
            as TAI. See https://en.wikipedia.org/wiki/International_Atomic_Time.
            The relationship between the three major time systems -- TAI, GPS, and UTC -- is as follows:
            TAI = GPS + 19 seconds TAI = UTC + LS + 10 seconds
            Where "LS" is the current number of leap seconds: https://en.wikipedia.org/wiki/Leap_second.
            Cyphal applications should only rely on TAI whenever a global time system is needed. GPS time is strongly
            discouraged for reasons of consistency across different positioning systems and applications.
            */
            [Version(0, 1), Sealed]
            public class TAIInfo_0_1 {
                /**
                [second] The fixed difference, in seconds, between TAI and GPS time. Does not change ever. Systems that use
                GPS time as a reference should convert that to TAI by adding this difference.
                */
                public const byte DIFFERENCE_TAI_MINUS_GPS = 19;
                public const ushort DIFFERENCE_TAI_MINUS_UTC_UNKNOWN = 0;
                /**
                The current difference between TAI and UTC, if known. If unknown, set to zero. This value may change states
                between known and unknown while the master is running, depending on its ability to obtain robust values from
                external sources. This value may change twice a year, possibly while the system is running;
                https://en.wikipedia.org/wiki/Leap_second. Since the rotation of Earth is decelerating, this value may only be
                positive. Do not use outside Earth. For reference, here is the full list of recorded TAI-UTC difference
                values, valid at the time of writing: Date     | TAI-UTC difference [second]
                ----------|----------------------------- Jan 1972 | 10 Jul 1972 | 11 Jan 1973 | 12 Jan 1974 | 13 Jan 1975 | 14
                Jan 1976 | 15 Jan 1977 | 16 Jan 1978 | 17 Jan 1979 | 18 Jan 1980 | 19 Jul 1981 | 20 Jul 1982 | 21 Jul 1983 |
                22 Jul 1985 | 23 Jan 1988 | 24 Jan 1990 | 25 Jan 1991 | 26 Jul 1992 | 27 Jul 1993 | 28 Jul 1994 | 29 Jan 1996
                | 30 Jul 1997 | 31 Jan 1999 | 32 Jan 2006 | 33 Jan 2009 | 34 Jul 2012 | 35 Jul 2015 | 36 Jan 2017 | 37 As of
                2020, the future of the leap second and the relation between UTC and TAI remains uncertain.
                */
                [MinMax(0, 1023)] ushort difference_tai_minus_utc;
            }

            /**
            Time system enumeration. The time system shall be the same for all masters in the network. It cannot be
            changed while the network is running.
            */
            [Version(0, 1), Sealed]
            public class TimeSystem_0_1 {
                /**
                Monotonic time since boot. Monotonic time is a time reference that doesn't change rate or make leaps.
                */
                public const byte MONOTONIC_SINCE_BOOT = 0;
                /**
                International Atomic Time; https://en.wikipedia.org/wiki/International_Atomic_Time. The timestamp value
                contains the number of microseconds elapsed since 1970-01-01T00:00:00Z TAI. TAI is always a fixed integer
                number of seconds ahead of GPS time. Systems that use GPS time as a reference should convert that to TAI by
                adding the fixed difference. GPS time is not supported for reasons of consistency across different positioning
                systems and applications.
                */
                public const byte TAI = 1;
                /**
                Application-specific time system of unknown properties.
                */
                public const byte APPLICATION_SPECIFIC = 15;
                [CastMode("truncated"), MinMax(0, 15)] byte value;
            }
        }

